// Crash-safe "replace this file" — readers see the old version or the new one, never half.
const fs = require('fs');
const path = require('path');

function writeFileAtomic(target, data) {
  const dir = path.dirname(target);
  const tmp = path.join(dir, `.${path.basename(target)}.${process.pid}.tmp`);
  const fd = fs.openSync(tmp, 'w', 0o644);  // same directory => same file system
  try {
    fs.writeFileSync(fd, data);
    fs.fsyncSync(fd);                     // 1. new bytes are durable BEFORE they become visible
  } finally {
    fs.closeSync(fd);
  }
  try {
    fs.renameSync(tmp, target);           // 2. atomic swap of the directory entry
  } catch (err) {
    fs.rmSync(tmp, { force: true });
    throw err;
  }
  const dfd = fs.openSync(dir, 'r');      // 3. persist the rename itself (POSIX: fsync the dir)
  try { fs.fsyncSync(dfd); } finally { fs.closeSync(dfd); }
}

const file = path.join(require('os').tmpdir(), 'config.json');
writeFileAtomic(file, JSON.stringify({ version: 1 }));
writeFileAtomic(file, JSON.stringify({ version: 2 }));
console.log(fs.readFileSync(file, 'utf8'));   // {"version":2}
fs.unlinkSync(file);
